import shlex
from pathlib import Path
command = 'cat memo.txt'
def kernel_read(name):
    return Path(name).read_text(encoding='utf-8') if Path(name).exists() else 'missing'
def shell(command):
    tokens = shlex.split(command)
    return kernel_read(tokens[1])
print(shell(command))
